using Impersonate.Domain.AiModels;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace Impersonate.Infrastructure.Persistence.Configurations;
internal sealed class AiModelProfileConfiguration:IEntityTypeConfiguration<AiModelProfile>{public void Configure(EntityTypeBuilder<AiModelProfile>b){b.ToTable("AiModelProfiles");b.HasKey(x=>x.Id);b.Property(x=>x.DisplayName).HasMaxLength(150).IsRequired();b.Property(x=>x.Provider).HasMaxLength(50).IsRequired();b.Property(x=>x.ModelIdentifier).HasMaxLength(200).IsRequired();b.Property(x=>x.Description).HasMaxLength(1000);b.HasIndex(x=>new{x.Provider,x.ModelIdentifier}).IsUnique();}}
internal sealed class AgentModelAssignmentConfiguration:IEntityTypeConfiguration<AgentModelAssignment>{public void Configure(EntityTypeBuilder<AgentModelAssignment>b){b.ToTable("AgentModelAssignments");b.HasKey(x=>x.Id);b.Property(x=>x.AgentRole).HasConversion<string>().HasMaxLength(30);b.HasIndex(x=>new{x.ProjectId,x.AgentRole}).IsUnique().HasFilter("[ProjectId] IS NOT NULL");b.HasIndex(x=>x.AgentRole).IsUnique().HasFilter("[ProjectId] IS NULL");b.HasOne<AiModelProfile>().WithMany().HasForeignKey(x=>x.AiModelProfileId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Impersonate.Domain.Projects.Project>().WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Restrict);}}
